```typescript
/**
 * Trims whitespace and converts a string to uppercase.
 * @param input - The string to process
 * @returns Uppercase string without leading/trailing whitespace
 * @throws Error if input is not a string
 */
function cleanAndUppercase(input: string): string {
  // 1. Type assertion: Ensure it's a string (TypeScript won't force this)
  if (typeof input !== 'string') {
    throw new Error('Input must be a string');
  }

  // 2. Trim whitespace and convert to uppercase
  return input.trim().toUpperCase();
}

// Example usage:
console.log(cleanAndUppercase("  hello world  ")); // "HELLO WORLD"
```

### Why this is useful:
- ✅ **Type safety** (catches invalid inputs at compile time)
- ✅ **Clear documentation** (JSDoc for IDE tools)
- ✅ **Real-world use** (common string manipulation pattern)

